import { useCallback, useId, useState } from 'react';
import { Button, Modal } from '@jinx-ui/react';

type DeleteProjectButtonProps = {
  projectName?: string;
  onConfirm: () => void;
};

export default function DeleteProjectButton({ projectName, onConfirm }: DeleteProjectButtonProps) {
  const [isOpen, setIsOpen] = useState(false);
  const descriptionId = useId();

  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => setIsOpen(false), []);
  const confirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button tone="danger" onClick={open}>
        Удалить проект
      </Button>

      <Modal
        open={isOpen}
        onClose={close}
        title="Удалить проект?"
        aria-describedby={descriptionId}
      >
        <p
          id={descriptionId}
          className="jx-text"
          style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}
        >
          {projectName
            ? `Проект «${projectName}» будет удалён навсегда. Действие необратимо.`
            : 'Проект будет удалён навсегда. Действие необратимо.'}
        </p>

        <div
          className="jx-cluster"
          style={{
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 'var(--jx-space-2)',
            marginTop: 'var(--jx-space-4)',
          }}
        >
          <Button variant="ghost" onClick={close}>
            Отмена
          </Button>
          <Button tone="danger" onClick={confirm}>
            Удалить
          </Button>
        </div>
      </Modal>
    </>
  );
}

